#include "ContextFit.h"
#include "AutoFit.h"
#include "ModelCodec.h"
#include <iostream>
#include <set>
#include <stdexcept>
void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
nova::Sound phrase(double rate){nova::Sound s;s.sampleRate=rate;s.left.resize(static_cast<size_t>(rate*32));s.right=s.left;int notes[]={48,55,60,64,67,72};for(size_t i=0;i<s.left.size();++i){double t=i/rate;if(t<8)continue;int slot=std::min(23,static_cast<int>(t-8));double local=t-8-slot;if(local>.88)continue;double hz=440*std::pow(2.,(notes[slot%6]-69)/12.);double amp=(slot/6)%2?.12:.35,env=std::min(1.,local/.015)*std::min(1.,(.88-local)/.06);s.right[i]=static_cast<float>(amp*env*(std::sin(2*nova::pi*hz*local)+.2*std::sin(6*nova::pi*hz*local)));s.left[i]=-s.right[i]*.3f;}return s;}
int main(){try{
 std::atomic<bool> cancel{false};auto source=phrase(16000);float previous=0;auto profile=nova::analyseContext(source,cancel,[&](float value){check(value>=previous&&value>=0&&value<=1,"context progress monotonic");previous=value;});
 std::cout<<"events="<<profile.events<<" unique="<<profile.uniqueNotes<<" picked="<<profile.picked.size()<<" usable="<<profile.usableFraction<<'\n';for(const auto& n:profile.picked)std::cout<<n.note<<" "<<n.range.start<<"-"<<n.range.end<<" velocity="<<n.velocity<<'\n';
 check(profile.duration==32&&profile.events>=20&&profile.uniqueNotes==6,"whole long phrase analysed, including after 15s");check(profile.picked.size()>3&&profile.picked.size()<=8,"multiple informative note/dynamic zones");std::set<int> notes;bool late=false;
 for(const auto& n:profile.picked){check(n.range.valid(32)&&n.range.length()<=2.001,"bounded short representative notes");check(n.range.start>=7.9,"initial silence excluded");notes.insert(n.note);late|=n.range.start>15;auto clip=nova::extractContextNote(source,n);check(clip.tonal&&clip.root==n.note,"extracted note independently confirms coarse pitch");check(n.velocity>=.2&&n.velocity<=1&&n.confidence>.8,"relative intensity / confidence bounds");}
 check(notes.size()==6&&late,"register coverage and useful late context");
 float before=0;auto learned=nova::learnContextInstrument(source,125.25,160,cancel,true,[&](int,int,double,float value){check(value>=before&&value<=1,"full context fit progress");before=value;});check(learned.fit.valid&&learned.bank&&learned.bank->count==8,"actual context pipeline learns all eight representative zones");check(learned.fit.parameters.useZones&&learned.fit.parameters.engine==1,"learned instrument routes to synthesised bank");check(learned.analysis.picked.front().range.start>125.25&&learned.analysis.picked.front().range.end<157.25,"representative ranges are absolute source positions");check(before==1,"full context fit completes progress");
 nova::ZoneBank bank;for(size_t i=0;i<std::min<size_t>(4,profile.picked.size());++i){auto note=nova::extractContextNote(source,profile.picked[i]);auto target=nova::makeTarget(note,note.root,22050,false);auto fit=nova::fitParameters(target,nova::Params{},20,cancel,{},2,{},false,true);check(fit.valid&&fit.model,"context note produces oscillator model");bank.zones[bank.count++]={*fit.model,profile.picked[i].velocity};}auto bytes=nova::encodeZones(bank);check(bank.valid()&&!bytes.empty(),"context bank has persistent synthesised models");
 for(double limit:{3.,60.}){auto range=nova::SelectionRange::between(125.25,205.25,3600,limit);check(range.valid(3600,limit)&&std::abs(range.length()-limit)<1e-8,"short/context selection caps");range.move(3590,3600,limit);check(range.valid(3600,limit),"context move EOF");range.resizeStart(0,3600,limit);range.resizeEnd(9000,3600,limit);check(range.valid(3600,limit),"context handles");auto span=nova::sampleSpan(range,96000,345600000,limit);check(span.count>0&&span.count<=static_cast<int64_t>(limit*96000)+1,"context exact frames");}
 nova::SelectionRange longRange{10,60};check(nova::sampleSpan(longRange,48000,48000*90).count==0,"legacy single-note readers reject long span");check(nova::sampleSpan(longRange,48000,48000*90,60).count==2400000,"explicit context span accepted");
 nova::Sound silent;silent.sampleRate=8000;silent.left.resize(64000);silent.right=silent.left;check(nova::analyseContext(silent,cancel).picked.empty(),"silent context rejected");
 auto cancelled=nova::analyseContext(source,cancel,[&](float){cancel.store(true);});check(cancelled.cancelled,"context scan cancellation");cancel.store(false);
 auto other=phrase(48000);auto high=nova::analyseContext(other,cancel);check(high.uniqueNotes==6&&!high.picked.empty(),"higher source rate context");
 std::cout<<"PASS: 32s context, late notes, relative dynamics, stereo, register diversity, clipped note verification, synthesis bank, limits/frames, silence, cancellation and two source rates\n";
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
